'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),http=require('node:http');
const {context,OpenAICompatibleAdapter,AICommunicationGateway,createGateway}=require('../../lara/llm');
const {generationPolicy}=require('../../lara/llm/policy'),{validate}=require('../../lara/validation');
async function endpoint(handler,run){const server=http.createServer(handler);await new Promise(r=>server.listen(0,'127.0.0.1',r));try{await run(`http://127.0.0.1:${server.address().port}`);}finally{server.closeAllConnections();await new Promise(r=>server.close(r));}}
const input={question:'What is Known Standard?',language:'English',passages:[{title:'Known Standard',text:'Known Standard governs evidence.'}]};
test('multilingual byte budget prioritizes evidence and redacts contact history',()=>{const result=context({...input,question:'问'.repeat(5000),passages:Array.from({length:8},()=>({text:'界'.repeat(4000),title:'Known Standard'})),history:Array.from({length:10},()=>({text:'person@example.test '+'界'.repeat(5000),role:'user'}))},8000);assert(Buffer.byteLength(JSON.stringify(result))<=8000);assert(result.canonical_sources.length>0);assert(!JSON.stringify(result).includes('@'));assert(!JSON.stringify(result).includes('\uFFFD'));});
test('public report-only, identity ambiguity and explicit boundaries block model calls',()=>{const base={configured:true,question:'Explain Known Standard',passages:input.passages};assert.equal(generationPolicy({...base,publicReportOnly:true}).reason,'report_only');assert.equal(generationPolicy({...base,identity:{status:'AMBIGUOUS'}}).allowed,false);assert.equal(generationPolicy({...base,question:'Can you approve a standard?'}).allowed,false);assert.equal(generationPolicy({...base,passages:[],question:'What is Unknown Standard?'}).reason,'missing_evidence');assert.equal(generationPolicy({...base,passages:[],question:'Hello, LaRA.'}).scope,'conversation');});
test('general conversation cannot smuggle unsupported canonical claims',()=>{assert.equal(validate('Hello, I am LaRA.','hello',[],{scope:'conversation'}).ok,true);assert.equal(validate('The New Standard is official.','hello',[],{scope:'conversation'}).ok,false);assert.equal(validate('Schválila som štandard.','test',input.passages).ok,false);assert.equal(validate('Ich habe den Standard genehmigt.','test',input.passages).ok,false);});
test('provider rejects oversized wire response and safely normalizes invalid JSON',async()=>{await endpoint((req,res)=>res.end('x'.repeat(70000)),async url=>{const adapter=new OpenAICompatibleAdapter({baseUrl:url,apiKey:'synthetic',model:'synthetic'});await assert.rejects(adapter.generate(input),e=>e.kind==='response_too_large');});await endpoint((req,res)=>res.end('not json'),async url=>{await assert.rejects(new OpenAICompatibleAdapter({baseUrl:url,apiKey:'synthetic',model:'synthetic'}).generate(input),e=>e.kind==='provider_error');});});
test('timeout, pre-aborted request and redirects do not leak provider details',async()=>{await endpoint(()=>{},async url=>{const adapter=new OpenAICompatibleAdapter({baseUrl:url,apiKey:'synthetic',model:'synthetic',timeout:40});await assert.rejects(adapter.generate(input),e=>e.kind==='timeout');const controller=new AbortController();controller.abort();await assert.rejects(adapter.generate({...input,signal:controller.signal}),e=>e.kind==='cancelled');});await endpoint((req,res)=>{res.writeHead(302,{location:'https://example.invalid/steal'});res.end();},async url=>{await assert.rejects(new OpenAICompatibleAdapter({baseUrl:url,apiKey:'synthetic',model:'synthetic'}).generate(input),e=>e.kind==='provider_error');});});
test('rate limit cooldown prevents immediate retry storms',async()=>{let calls=0;await endpoint((req,res)=>{calls++;res.writeHead(429,{'retry-after':'2'});res.end('private provider message');},async url=>{const adapter=new OpenAICompatibleAdapter({baseUrl:url,apiKey:'synthetic',model:'synthetic'});for(let i=0;i<2;i++)await assert.rejects(adapter.generate(input),e=>e.kind==='rate_limited'&&!e.message.includes('private'));assert.equal(calls,1);});});
test('configured fallback reports actual provider/model without cross-provider credentials',async()=>{const gateway=new AICommunicationGateway({primary:{name:'primary',async generate(){throw Error('synthetic');}},fallback:{name:'secondary',config:{model:'model-b'},async generate(){return 'Known Standard governs evidence.';}}});const result=await gateway.generateDetailed(input);assert.equal(result.provider,'secondary');assert.equal(result.model,'model-b');assert.equal(result.fallback_used,true);assert.equal(gateway.snapshot().fallback_generated,1);assert.throws(()=>createGateway({LLM_PROVIDER:'openrouter',LLM_MODEL:'one',LLM_API_KEY:'secret',LLM_FALLBACK_PROVIDER:'openai-compatible'}),e=>e.kind==='invalid_configuration');});
test('concurrency limit stays bounded and recovers after completion',async()=>{let finish;const gateway=new AICommunicationGateway({maxConcurrent:1,primary:{async generate(){return new Promise(r=>{finish=r;});}}});const first=gateway.generate(input);await assert.rejects(gateway.generate(input),e=>e.kind==='busy');finish('Known Standard governs evidence.');await first;assert.equal(gateway.snapshot().active,0);});
test('external HTTP and credential-bearing endpoints fail configuration closed',()=>{for(const url of ['http://example.test/v1','https://key@example.test/v1','https://example.test/v1?key=secret'])assert.throws(()=>createGateway({LLM_PROVIDER:'openai-compatible',LLM_MODEL:'test',LLM_API_KEY:'synthetic',LLM_BASE_URL:url}),e=>e.kind==='invalid_configuration');});
